    def orangesRotting(self, grid: List[List[int]]) -> int:
        m, n = (len(grid), len(grid[0]))
        bad = deque()
        fresh = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 2:
                    bad.append((i, j))
